INSERT INTO public.proverbs (
    kannada, transliteration, english_meaning, kannada_meaning,
    category, category_kn, situation, situation_kn, tags, contributor, likes, is_verified
) VALUES
    ('ಸೊಸೆ ಸತ್ತರೆ ಸೊಬಾನ ಮಗ ಸತ್ತರೆ ಮನೆ ಹಾಳು', 'Sose sattare sobaana maga sattare mane haalu', '[Translation in progress] Traditional folk wisdom: "ಸೊಸೆ ಸತ್ತರೆ ಸೊಬಾನ ಮಗ ಸತ್ತರೆ ಮನೆ ಹಾಳು". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಸೊಸೆ ಸತ್ತರೆ ಸೊಬಾನ ಮಗ ಸತ್ತರೆ ಮನೆ ಹಾಳು". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಸೊಸೆ","ಸತ್ತರೆ","ಸೊಬಾನ","ಮನೆ","ಹಾಳು","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಎಣ್ಣೆ ಬಂದಾಗ ಕಣ್ಣು ಮುಚ್ಚಿಕೊಂಡ ಹಾಗೆ', 'Enne bamdaaga kannu muchchikomda haage', '[Translation in progress] Traditional folk wisdom: "ಎಣ್ಣೆ ಬಂದಾಗ ಕಣ್ಣು ಮುಚ್ಚಿಕೊಂಡ ಹಾಗೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಎಣ್ಣೆ ಬಂದಾಗ ಕಣ್ಣು ಮುಚ್ಚಿಕೊಂಡ ಹಾಗೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಎಣ್ಣೆ","ಬಂದಾಗ","ಕಣ್ಣು","ಮುಚ್ಚಿಕೊಂಡ","ಹಾಗೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅಶ್ವಥ ಸುತ್ತಿದರೆ ಮಕ್ಕಳಾಗುತ್ತೆ ಅಂದ್ರೆ ಸುತ್ತು ಸುತ್ತಿಗೂ ಹೊಟ್ಟೆ ಮುಟ್ಟಿ ನೋಡಿಕೊಂಡಳಂತೆ', 'Ashvatha suttidare makkalaagutte amdre suttu suttigoo hotte mutti noodikomdalamte', '[Translation in progress] Traditional folk wisdom: "ಅಶ್ವಥ ಸುತ್ತಿದರೆ ಮಕ್ಕಳಾಗುತ್ತೆ ಅಂದ್ರೆ ಸುತ್ತು ಸುತ್ತಿಗೂ ಹೊಟ್ಟೆ ಮುಟ್ಟಿ ನೋಡಿಕೊಂಡಳಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅಶ್ವಥ ಸುತ್ತಿದರೆ ಮಕ್ಕಳಾಗುತ್ತೆ ಅಂದ್ರೆ ಸುತ್ತು ಸುತ್ತಿಗೂ ಹೊಟ್ಟೆ ಮುಟ್ಟಿ ನೋಡಿಕೊಂಡಳಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅಶ್ವಥ","ಸುತ್ತಿದರೆ","ಮಕ್ಕಳಾಗುತ್ತೆ","ಅಂದ್ರೆ","ಸುತ್ತು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತಾನು ನೆಟ್ಟ ಬೀಳು (ಬಳ್ಳಿ) ತನ್ನ ಎದೆಗೆ ಹಬ್ಬಿತು', 'Taanu netta beelu (balli) tanna edege habbitu', '[Translation in progress] Traditional folk wisdom: "ತಾನು ನೆಟ್ಟ ಬೀಳು (ಬಳ್ಳಿ) ತನ್ನ ಎದೆಗೆ ಹಬ್ಬಿತು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತಾನು ನೆಟ್ಟ ಬೀಳು (ಬಳ್ಳಿ) ತನ್ನ ಎದೆಗೆ ಹಬ್ಬಿತು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತಾನು","ನೆಟ್ಟ","ಬೀಳು","ಬಳ್ಳಿ","ತನ್ನ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕೈಯೆತ್ತಿ ಕೊಡಲಿಲ್ಲ ಮೈಯ್ಯ ದಂಡಿಸಲಿಲ್ಲ', 'Kaiyetti kodalilla maiyya damdisalilla', '[Translation in progress] Traditional folk wisdom: "ಕೈಯೆತ್ತಿ ಕೊಡಲಿಲ್ಲ ಮೈಯ್ಯ ದಂಡಿಸಲಿಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕೈಯೆತ್ತಿ ಕೊಡಲಿಲ್ಲ ಮೈಯ್ಯ ದಂಡಿಸಲಿಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕೈಯೆತ್ತಿ","ಕೊಡಲಿಲ್ಲ","ಮೈಯ್ಯ","ದಂಡಿಸಲಿಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಉದ್ಯೋಗವೇ ಗಂಡಸಿಗೆ ಲಕ್ಷಣ', 'Udyoogavee gamdasige lakshana', '[Translation in progress] Traditional folk wisdom: "ಉದ್ಯೋಗವೇ ಗಂಡಸಿಗೆ ಲಕ್ಷಣ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಉದ್ಯೋಗವೇ ಗಂಡಸಿಗೆ ಲಕ್ಷಣ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಉದ್ಯೋಗವೇ","ಗಂಡಸಿಗೆ","ಲಕ್ಷಣ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕಲ್ಲಲ್ಲಿ ಇಟ್ಟವನ ಬೆಲ್ಲದಲ್ಲಿ ಇಡಬೇಕು', 'Kallalli ittavana belladalli idabeeku', '[Translation in progress] Traditional folk wisdom: "ಕಲ್ಲಲ್ಲಿ ಇಟ್ಟವನ ಬೆಲ್ಲದಲ್ಲಿ ಇಡಬೇಕು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕಲ್ಲಲ್ಲಿ ಇಟ್ಟವನ ಬೆಲ್ಲದಲ್ಲಿ ಇಡಬೇಕು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕಲ್ಲಲ್ಲಿ","ಇಟ್ಟವನ","ಬೆಲ್ಲದಲ್ಲಿ","ಇಡಬೇಕು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಮಾಡೋದು ಅನಾಚಾರ; ಮನೆ ಮುಂದೆ ಬೃಂದಾವನ', 'Maadoodu anaachaara; mane mumde brumdaavana', '[Translation in progress] Traditional folk wisdom: "ಮಾಡೋದು ಅನಾಚಾರ; ಮನೆ ಮುಂದೆ ಬೃಂದಾವನ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಮಾಡೋದು ಅನಾಚಾರ; ಮನೆ ಮುಂದೆ ಬೃಂದಾವನ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಮಾಡೋದು","ಅನಾಚಾರ","ಮನೆ","ಮುಂದೆ","ಬೃಂದಾವನ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ದುಡ್ಡು ಕೊಟ್ಟು ದೆವ್ವ ಹಿಡಿಸಿಕೊಂಡ ಹಾಗೆ', 'Duddu kottu devva hidisikomda haage', '[Translation in progress] Traditional folk wisdom: "ದುಡ್ಡು ಕೊಟ್ಟು ದೆವ್ವ ಹಿಡಿಸಿಕೊಂಡ ಹಾಗೆ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ದುಡ್ಡು ಕೊಟ್ಟು ದೆವ್ವ ಹಿಡಿಸಿಕೊಂಡ ಹಾಗೆ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ದುಡ್ಡು","ಕೊಟ್ಟು","ದೆವ್ವ","ಹಿಡಿಸಿಕೊಂಡ","ಹಾಗೆ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹೆಣ್ಣಿನ ಸೊಬಗನು ಕಣ್ಣಾರೆ ಕಂಡು ಬಯಸದ ಅಣ್ಣಗಳು ಅದಾರು', 'Hennina sobaganu kannaare kamdu bayasada annagalu adaaru', '[Translation in progress] Traditional folk wisdom: "ಹೆಣ್ಣಿನ ಸೊಬಗನು ಕಣ್ಣಾರೆ ಕಂಡು ಬಯಸದ ಅಣ್ಣಗಳು ಅದಾರು". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹೆಣ್ಣಿನ ಸೊಬಗನು ಕಣ್ಣಾರೆ ಕಂಡು ಬಯಸದ ಅಣ್ಣಗಳು ಅದಾರು". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹೆಣ್ಣಿನ","ಸೊಬಗನು","ಕಣ್ಣಾರೆ","ಕಂಡು","ಬಯಸದ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತೀರಕ್ಕೆ ಬಂದ ಮೇಲೆ ತೆರೆಯ ಭಯವೇ', 'Teerakke bamda meele tereya bhayavee', '[Translation in progress] Traditional folk wisdom: "ತೀರಕ್ಕೆ ಬಂದ ಮೇಲೆ ತೆರೆಯ ಭಯವೇ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತೀರಕ್ಕೆ ಬಂದ ಮೇಲೆ ತೆರೆಯ ಭಯವೇ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತೀರಕ್ಕೆ","ಬಂದ","ಮೇಲೆ","ತೆರೆಯ","ಭಯವೇ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅರುಗೆಟ್ಟ ನಿದ್ದೆ (=ಅರಿವಿಲ್ಲದೆ ಮಲಗಿರುವುದು) ಇರಗೆಟ್ಟು (=ಇರವು ಗೆಟ್ಟು) ಸತ್ತಂತೆ', 'Arugetta nidde (=arivillade malagiruvudu) iragettu (=iravu gettu) sattamte', '[Translation in progress] Traditional folk wisdom: "ಅರುಗೆಟ್ಟ ನಿದ್ದೆ (=ಅರಿವಿಲ್ಲದೆ ಮಲಗಿರುವುದು) ಇರಗೆಟ್ಟು (=ಇರವು ಗೆಟ್ಟು) ಸತ್ತಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅರುಗೆಟ್ಟ ನಿದ್ದೆ (=ಅರಿವಿಲ್ಲದೆ ಮಲಗಿರುವುದು) ಇರಗೆಟ್ಟು (=ಇರವು ಗೆಟ್ಟು) ಸತ್ತಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅರುಗೆಟ್ಟ","ನಿದ್ದೆ","=ಅರಿವಿಲ್ಲದೆ","ಮಲಗಿರುವುದು","ಇರಗೆಟ್ಟು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
