    ('ಘಟಾ (ದೇಹ ) ಇದ್ದರೆ ಮಠಾ ಕಟ್ಟಿಸಬಹುದು', 'Ghataa (deeha ) iddare mathaa kattisabahudu', '[Translation in progress] Traditional folk wisdom: "ಘಟಾ (ದೇಹ ) ಇದ್ದರೆ ಮಠಾ ಕಟ್ಟಿಸಬಹುದು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಘಟಾ (ದೇಹ ) ಇದ್ದರೆ ಮಠಾ ಕಟ್ಟಿಸಬಹುದು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಘಟಾ","ದೇಹ","ಇದ್ದರೆ","ಮಠಾ","ಕಟ್ಟಿಸಬಹುದು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಆಡಿ ಪೋಕರಿ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದಕಿಂತ ಆಡದೆ ಮೂಗ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದು ಮೇಲು', 'Aadi pookari annisikolluvudakimta aadade mooga annisikolluvudu meelu', '[Translation in progress] Traditional folk wisdom: "ಆಡಿ ಪೋಕರಿ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದಕಿಂತ ಆಡದೆ ಮೂಗ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದು ಮೇಲು". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಆಡಿ ಪೋಕರಿ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದಕಿಂತ ಆಡದೆ ಮೂಗ ಅನ್ನಿಸಿಕೊಳ್ಳುವುದು ಮೇಲು". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಆಡಿ","ಪೋಕರಿ","ಅನ್ನಿಸಿಕೊಳ್ಳುವುದಕಿಂತ","ಆಡದೆ","ಮೂಗ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ನರಿ ಕೊಂಬಿದ್ದರೂ ನರರಿಗೆ ಹೆದರಬೇಕು', 'Nari kombiddaroo nararige hedarabeeku', '[Translation in progress] Traditional folk wisdom: "ನರಿ ಕೊಂಬಿದ್ದರೂ ನರರಿಗೆ ಹೆದರಬೇಕು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ನರಿ ಕೊಂಬಿದ್ದರೂ ನರರಿಗೆ ಹೆದರಬೇಕು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ನರಿ","ಕೊಂಬಿದ್ದರೂ","ನರರಿಗೆ","ಹೆದರಬೇಕು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ನೀ ಡಬ್ಬಿದ್ದು ಸಾಯಿ', 'Nee dabbiddu saayi', '[Translation in progress] Traditional folk wisdom: "ನೀ ಡಬ್ಬಿದ್ದು ಸಾಯಿ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ನೀ ಡಬ್ಬಿದ್ದು ಸಾಯಿ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಡಬ್ಬಿದ್ದು","ಸಾಯಿ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಸೋಲಿಲ್ಲದ ಸರದಾರನಿಲ್ಲ, ಸಂಗಮವಿಲ್ಲದ ಸಾವಿಲ್ಲ', 'Soolillada saradaaranilla, samgamavillada saavilla', '[Translation in progress] Traditional folk wisdom: "ಸೋಲಿಲ್ಲದ ಸರದಾರನಿಲ್ಲ, ಸಂಗಮವಿಲ್ಲದ ಸಾವಿಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಸೋಲಿಲ್ಲದ ಸರದಾರನಿಲ್ಲ, ಸಂಗಮವಿಲ್ಲದ ಸಾವಿಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಸೋಲಿಲ್ಲದ","ಸರದಾರನಿಲ್ಲ","ಸಂಗಮವಿಲ್ಲದ","ಸಾವಿಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬೆಟ್ಟ ಮಹಮ್ಮದನ ಬಳಿ ಬರಲ್ಲ,ಮಹಮ್ಮದನೇ ಬೆಟ್ಟದ ಬಳಿ ಹೋಗಬೇಕು', 'Betta mahammadana bali baralla,mahammadanee bettada bali hoogabeeku', '[Translation in progress] Traditional folk wisdom: "ಬೆಟ್ಟ ಮಹಮ್ಮದನ ಬಳಿ ಬರಲ್ಲ,ಮಹಮ್ಮದನೇ ಬೆಟ್ಟದ ಬಳಿ ಹೋಗಬೇಕು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬೆಟ್ಟ ಮಹಮ್ಮದನ ಬಳಿ ಬರಲ್ಲ,ಮಹಮ್ಮದನೇ ಬೆಟ್ಟದ ಬಳಿ ಹೋಗಬೇಕು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬೆಟ್ಟ","ಮಹಮ್ಮದನ","ಬಳಿ","ಬರಲ್ಲಮಹಮ್ಮದನೇ","ಬೆಟ್ಟದ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಪಕ್ಕದ ಮನೆ ಊಟ ಎಂದೂ ಹೆಚ್ಚು ರುಚಿ', 'Pakkada mane oota emdoo hechchu ruchi', '[Translation in progress] Traditional folk wisdom: "ಪಕ್ಕದ ಮನೆ ಊಟ ಎಂದೂ ಹೆಚ್ಚು ರುಚಿ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಪಕ್ಕದ ಮನೆ ಊಟ ಎಂದೂ ಹೆಚ್ಚು ರುಚಿ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಪಕ್ಕದ","ಮನೆ","ಎಂದೂ","ಹೆಚ್ಚು","ರುಚಿ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಎಂಥೆಂತದ್ದೊ ಅಂತರಿಸಿದ ಮೇಲೆ ಸಂಕ್ರಾಂತಿ ಬಂತಂತೆ.. ಮೂಸೋಕೆ', 'Emthemtaddo amtarisida meele samkraamti bamtamte.. moosooke', '[Translation in progress] Traditional folk wisdom: "ಎಂಥೆಂತದ್ದೊ ಅಂತರಿಸಿದ ಮೇಲೆ ಸಂಕ್ರಾಂತಿ ಬಂತಂತೆ.. ಮೂಸೋಕೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಎಂಥೆಂತದ್ದೊ ಅಂತರಿಸಿದ ಮೇಲೆ ಸಂಕ್ರಾಂತಿ ಬಂತಂತೆ.. ಮೂಸೋಕೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಎಂಥೆಂತದ್ದೊ","ಅಂತರಿಸಿದ","ಮೇಲೆ","ಸಂಕ್ರಾಂತಿ","ಬಂತಂತೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ನಮಸ್ಕಾರ ಮಾಡಲು ಹೋಗಿ ದೇವಸ್ಥಾನದ ಗೋಪುರ ತಲೆ ಮೇಲೆ ಬಿತ್ತು', 'Namaskaara maadalu hoogi deevasthaanada goopura tale meele bittu', '[Translation in progress] Traditional folk wisdom: "ನಮಸ್ಕಾರ ಮಾಡಲು ಹೋಗಿ ದೇವಸ್ಥಾನದ ಗೋಪುರ ತಲೆ ಮೇಲೆ ಬಿತ್ತು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ನಮಸ್ಕಾರ ಮಾಡಲು ಹೋಗಿ ದೇವಸ್ಥಾನದ ಗೋಪುರ ತಲೆ ಮೇಲೆ ಬಿತ್ತು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ನಮಸ್ಕಾರ","ಮಾಡಲು","ಹೋಗಿ","ದೇವಸ್ಥಾನದ","ಗೋಪುರ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬೀದೀಲಿ ಹೋಗ್ತಿದ್ದ ಮಾರಿಯನ್ನು ಕರೆದು ಮನೆಗೆ ಸೇರಿಸಿಕೊಂಡಂತೆ', 'Beedeeli hoogtidda maariyannu karedu manege seerisikomdamte', '[Translation in progress] Traditional folk wisdom: "ಬೀದೀಲಿ ಹೋಗ್ತಿದ್ದ ಮಾರಿಯನ್ನು ಕರೆದು ಮನೆಗೆ ಸೇರಿಸಿಕೊಂಡಂತೆ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬೀದೀಲಿ ಹೋಗ್ತಿದ್ದ ಮಾರಿಯನ್ನು ಕರೆದು ಮನೆಗೆ ಸೇರಿಸಿಕೊಂಡಂತೆ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬೀದೀಲಿ","ಹೋಗ್ತಿದ್ದ","ಮಾರಿಯನ್ನು","ಕರೆದು","ಮನೆಗೆ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬುದ್ಧಿ ಬಲಿಯದವನಿಗೆ ಮನೆ ಎಲ್ಲಾ ಸೌದೆ', 'Buddhi baliyadavanige mane ellaa saude', '[Translation in progress] Traditional folk wisdom: "ಬುದ್ಧಿ ಬಲಿಯದವನಿಗೆ ಮನೆ ಎಲ್ಲಾ ಸೌದೆ". Context: Guidance on education and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬುದ್ಧಿ ಬಲಿಯದವನಿಗೆ ಮನೆ ಎಲ್ಲಾ ಸೌದೆ". ಇದು ಶಿಕ್ಷಣ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'education', 'ಶಿಕ್ಷಣ', 'Used in daily conversations to illustrate education principles and life lessons.', 'ಶಿಕ್ಷಣ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬುದ್ಧಿ","ಬಲಿಯದವನಿಗೆ","ಮನೆ","ಎಲ್ಲಾ","ಸೌದೆ","ಶಿಕ್ಷಣ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
